// Code generated by Specula harness-generation. DO NOT EDIT.
package bft

import (
	"encoding/json"
	"os"
	"sync"
	"time"
)

// TLATrace is the global trace emitter. Nil = disabled.
var TLATrace *tlaTracer

type tlaTracer struct {
	mu   sync.Mutex
	file *os.File
}

// InitTLATrace opens the trace file and enables emission.
// Call once per test scenario before starting nodes.
func InitTLATrace(path string) {
	f, err := os.Create(path)
	if err != nil {
		panic("tla_trace: cannot create " + path + ": " + err.Error())
	}
	TLATrace = &tlaTracer{file: f}
}

// CloseTLATrace flushes and closes the trace file. Safe to call if nil.
func CloseTLATrace() {
	if TLATrace == nil {
		return
	}
	TLATrace.mu.Lock()
	_ = TLATrace.file.Sync()
	_ = TLATrace.file.Close()
	TLATrace.mu.Unlock()
	TLATrace = nil
}

// Emit writes one NDJSON trace line. Thread-safe.
// fields must NOT contain "tag" or "ts" — they are added here.
func (t *tlaTracer) Emit(fields map[string]interface{}) {
	if t == nil {
		return
	}
	fields["tag"] = "trace"
	fields["ts"] = time.Now().UnixNano()
	line, err := json.Marshal(fields)
	if err != nil {
		return
	}
	t.mu.Lock()
	_, _ = t.file.Write(line)
	_, _ = t.file.Write([]byte("\\n"))
	t.mu.Unlock()
}
