// startNodes starts consensus on all nodes, then starts network message delivery.
// (Copied from basic_test.go pattern; avoids import cycle.)
func startNodesTLA(nodes []*App, network *Network) {
	for _, n := range nodes {
		if err := n.Consensus.Start(); err != nil {
			panic(fmt.Sprintf("Consensus start error: %v", err))
		}
	}
	network.StartServe()
}

// waitAllDelivered collects exactly count deliveries from each of the given nodes.
func waitAllDelivered(nodes []*App, count int, timeout time.Duration) error {
	type result struct {
		idx int
		err error
	}
	ch := make(chan result, len(nodes))
	for i, n := range nodes {
		go func(i int, n *App) {
			timer := time.NewTimer(timeout)
			defer timer.Stop()
			for j := 0; j < count; j++ {
				select {
				case <-n.Delivered:
				case <-timer.C:
					ch <- result{i, fmt.Errorf("node %d timed out waiting for delivery %d", i+1, j+1)}
					return
				}
			}
			ch <- result{i, nil}
		}(i, n)
	}
	for range nodes {
		r := <-ch
		if r.err != nil {
			return r.err
		}
	}
	return nil
}

// TestTLATraceNormal exercises the happy-path consensus with 4 nodes and 3 decisions.
// Expected events: propose, pre_prepare, decide, change_role, update_view, update_decisions.
func TestTLATraceNormal(t *testing.T) {
	t.Parallel()
	traceFile := fmt.Sprintf("%s/traces/trace_normal.ndjson", "${OUTPUT}")
	bft.InitTLATrace(traceFile)
	defer bft.CloseTLATrace()

	network := NewNetwork()
	defer network.Shutdown()

	testDir, err := os.MkdirTemp("", t.Name())
	if err != nil {
		t.Fatalf("MkdirTemp: %v", err)
	}
	defer os.RemoveAll(testDir)

	const n = 4
	nodes := make([]*App, 0, n)
	for i := 1; i <= n; i++ {
		nodes = append(nodes, newNode(uint64(i), network, t.Name(), testDir, false, 0))
	}
	startNodesTLA(nodes, network)

	// Submit 3 requests from the leader (node 1).
	for i := 1; i <= 3; i++ {
		nodes[0].Submit(Request{ID: fmt.Sprintf("req-%d", i), ClientID: "alice"})
	}

	// Wait for all 4 nodes to deliver all 3 proposals (30 s total budget).
	if err := waitAllDelivered(nodes, 3, 30*time.Second); err != nil {
		t.Fatalf("waitAllDelivered: %v", err)
	}
}

// TestTLATraceViewChange exercises view change by isolating the leader.
// Expected events (in addition to normal-path events):
//   view_change_start, enter_new_view, update_view, update_decisions
//   hb_timeout fires if the heartbeat monitor triggers before request timeout.
//   vc_deliver / vc_validate fire if a lagging node catches up during view-data exchange.
func TestTLATraceViewChange(t *testing.T) {
	t.Parallel()
	traceFile := fmt.Sprintf("%s/traces/trace_view_change.ndjson", "${OUTPUT}")
	bft.InitTLATrace(traceFile)
	defer bft.CloseTLATrace()

	network := NewNetwork()
	defer network.Shutdown()

	testDir, err := os.MkdirTemp("", t.Name())
	if err != nil {
		t.Fatalf("MkdirTemp: %v", err)
	}
	defer os.RemoveAll(testDir)

	const n = 4
	nodes := make([]*App, 0, n)
	for i := 1; i <= n; i++ {
		nodes = append(nodes, newNode(uint64(i), network, t.Name(), testDir, false, 0))
	}
	startNodesTLA(nodes, network)

	// Let node 1 (leader for view 0) commit 1 proposal first.
	nodes[0].Submit(Request{ID: "before-vc", ClientID: "alice"})
	if err := waitAllDelivered(nodes, 1, 20*time.Second); err != nil {
		t.Fatalf("pre-VC delivery: %v", err)
	}

	// Isolate the leader (node 1). All peers stop receiving its messages;
	// leader also stops receiving from others.
	for i := 2; i <= n; i++ {
		nodes[0].DisconnectFrom(uint64(i))
		nodes[i-1].DisconnectFrom(1)
	}

	// Submit one more request — it will not be committed while leader is isolated,
	// causing followers to complain (RequestComplainTimeout=2s) and start a view change.
	nodes[1].Submit(Request{ID: "trigger-vc", ClientID: "bob"})

	// Wait for the view change to complete by watching for delivery on the remaining quorum.
	// Allow up to 60 seconds (RequestComplainTimeout=2s + ViewChangeTimeout=60s overhead).
	var wg sync.WaitGroup
	type delivResult struct {
		idx int
		ok  bool
	}
	resultCh := make(chan delivResult, n)
	for i := 1; i < n; i++ { // skip isolated leader (index 0)
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			timer := time.NewTimer(90 * time.Second)
			defer timer.Stop()
			// Collect 2 deliveries: the first was already done; the second is the VC proposal.
			for j := 0; j < 1; j++ {
				select {
				case <-nodes[i].Delivered:
					resultCh <- delivResult{i, true}
				case <-timer.C:
					resultCh <- delivResult{i, false}
					return
				}
			}
		}(i)
	}
	wg.Wait()
	close(resultCh)

	delivered := 0
	for r := range resultCh {
		if r.ok {
			delivered++
		}
	}
	if delivered < 2 { // quorum = 3 nodes, at least 2 non-leader nodes delivered
		t.Logf("view change delivery count: %d (may be timing-dependent)", delivered)
	}

	// Brief pause so trailing events (change_role, update_decisions) are flushed.
	time.Sleep(500 * time.Millisecond)
}

// TestTLATraceHBTimeout attempts to trigger HBM heartbeat timeout by manually
// advancing the HBM scheduler clock past the heartbeat timeout threshold.
// The leader (node 1) is stopped; follower HBM schedulers are driven manually.
func TestTLATraceHBTimeout(t *testing.T) {
	t.Parallel()
	traceFile := fmt.Sprintf("%s/traces/trace_hb_timeout.ndjson", "${OUTPUT}")
	bft.InitTLATrace(traceFile)
	defer bft.CloseTLATrace()

	network := NewNetwork()
	defer network.Shutdown()

	testDir, err := os.MkdirTemp("", t.Name())
	if err != nil {
		t.Fatalf("MkdirTemp: %v", err)
	}
	defer os.RemoveAll(testDir)

	// Allocate manual heartbeat clock channels for all nodes.
	hbChans := make([]chan time.Time, 5) // 1-indexed
	for i := 1; i <= 4; i++ {
		hbChans[i] = make(chan time.Time, 200)
	}

	const n = 4
	nodes := make([]*App, 0, n)
	for i := 1; i <= n; i++ {
		app := newNode(uint64(i), network, t.Name(), testDir, false, 0)
		// Replace the real clock with our manual channel BEFORE (re)starting.
		app.heartbeatTime = hbChans[i]
		app.Consensus.Stop()
		// Reset and restart with the manual clock.
		app.Setup()
		if err := app.Consensus.Start(); err != nil {
			t.Fatalf("node %d start: %v", i, err)
		}
		nodes = append(nodes, app)
	}
	network.StartServe()

	// Pump a few heartbeat ticks to let all nodes initialise their HBM state.
	t0 := time.Now()
	for i := 1; i <= n; i++ {
		for tick := 0; tick < 5; tick++ {
			hbChans[i] <- t0.Add(time.Duration(tick) * 10 * time.Millisecond)
		}
	}
	time.Sleep(200 * time.Millisecond)

	// Let node 1 commit one proposal (so nodes are in a known state).
	for i := 1; i <= n; i++ {
		for tick := 5; tick < 15; tick++ {
			hbChans[i] <- t0.Add(time.Duration(tick) * 10 * time.Millisecond)
		}
	}
	nodes[0].Submit(Request{ID: "before-hb", ClientID: "alice"})
	_ = waitAllDelivered(nodes, 1, 15*time.Second)

	// Now isolate the leader so followers stop receiving heartbeats.
	for i := 2; i <= n; i++ {
		nodes[0].DisconnectFrom(uint64(i))
		nodes[i-1].DisconnectFrom(1)
	}

	// Pump ticks past the LeaderHeartbeatTimeout (1 minute in fastConfig).
	// Each tick advances "now" by 90 seconds, so after 2 ticks the timeout fires.
	t1 := t0.Add(30 * time.Second)
	for i := 2; i <= n; i++ { // follower nodes only (node 1 is leader/isolated)
		for tick := 0; tick < 3; tick++ {
			hbChans[i] <- t1.Add(time.Duration(tick+1) * 90 * time.Second)
		}
	}
	// Also tick the leader's channel so it doesn't block.
	for tick := 0; tick < 3; tick++ {
		hbChans[1] <- t1.Add(time.Duration(tick+1) * 90 * time.Second)
	}

	// Wait for hb_timeout events to be emitted (give 10s).
	// We check by looking for view_change_start or just wait a fixed amount.
	var vcSeen sync.WaitGroup
	vcSeen.Add(1)
	go func() {
		defer vcSeen.Done()
		// Poll the trace file for hb_timeout events or wait 8s.
		deadline := time.Now().Add(8 * time.Second)
		for time.Now().Before(deadline) {
			data, _ := os.ReadFile(traceFile)
			if strings.Contains(string(data), "hb_timeout") {
				return
			}
			time.Sleep(100 * time.Millisecond)
		}
	}()
	vcSeen.Wait()
	time.Sleep(300 * time.Millisecond)
}
